from functools import cache

@cache                                   # top-down: plain recursion + memo
def ways(n: int) -> int:                 # climb n stairs taking 1 or 2 steps
    return 1 if n <= 1 else ways(n - 1) + ways(n - 2)

def edit_distance(a: str, b: str) -> int:
    m, n = len(a), len(b)
    # dp[i][j] = edits to turn a[:i] into b[:j]; one list per row (no aliasing)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(m + 1):
        dp[i][0] = i                     # delete all of a[:i]
    for j in range(n + 1):
        dp[0][j] = j                     # insert all of b[:j]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i - 1] == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:                        # delete, insert, replace
                dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])
    return dp[m][n]

def knapsack(items, cap: int) -> int:    # 0/1: items = [(weight, value)]
    best = [0] * (cap + 1)               # one row: best value per capacity
    for w, v in items:
        for c in range(cap, w - 1, -1):  # go DOWN so each item is used once
            best[c] = max(best[c], best[c - w] + v)
    return best[cap]
